j2:if.script:
// addAfterPageLoadedEvent runs after the page is loaded, ready, and displayed for use
addAfterPageLoadedEvent(function() {
    var nacmConfig = NOW.tableLevelNacmConfig;
    var element = "${jvar_element}";
    WWNA.loadAssets();
    var tempComponentId = '#' + element;
    var component = document.querySelector(tempComponentId);
    component.componentKey = element;
    component.documentTableName = "$[jvar_table]";
    component.documentSysId = "$[jvar_form_sys_id]";
    component.triggerProps = {
        "isButtonEmbedded": true
    };
    component.dialogProps = {};
    component.adminConfig = nacmConfig;
    component.caller = "ui16";
});
